package render

import (
	"strings"

	"github.com/alecthomas/chroma/v2/formatters/html"
	"github.com/alecthomas/chroma/v2/styles"
)

var (
	formatter  = html.New(html.WithClasses(true), html.ClassPrefix(HighlightClassPrefix))
	styleLight = styles.Get("github")
	styleDark  = styles.Get("github-dark")
)

// HighlightCSS returns the stylesheet for Markdown's highlight classes, generated by
// chroma's html.Formatter.WriteCSS with HighlightClassPrefix. Token rules are scoped under
// .hl-chroma; chroma's own .hl-bg and .hl-chroma wrapper rules stand alone.
// It is a light style wrapped in @media not all and (prefers-color-scheme: dark), followed
// by a dark style wrapped in @media (prefers-color-scheme: dark), so no light property
// (a bold weight, an error background) leaks into dark mode. The output is deterministic.
func HighlightCSS() string {
	var sb strings.Builder
	sb.WriteString("@media not all and (prefers-color-scheme: dark) {\n")
	if err := formatter.WriteCSS(&sb, styleLight); err != nil {
		panic(err)
	}
	sb.WriteString(".hl-chroma .hl-bp { color: #57606a } /* github's #6a737d is under 4.5:1 on the code background */\n")
	sb.WriteString("}\n@media (prefers-color-scheme: dark) {\n")
	if err := formatter.WriteCSS(&sb, styleDark); err != nil {
		panic(err)
	}
	sb.WriteString("}\n")
	return sb.String()
}
